 public static SivkaEntity horse;static boolean started,done;static int ticks,shot=-1;static final float[] PHASES={0,.12F,.27F,.40F,.56F,.70F,.86F};static final List<Map<String,Object>> frames=new ArrayList<>();static final Path O=Path.of("../../docs/implementation/stabilization269-20261026/poses-"+System.getProperty("slavicmyths.qa269.poseLabel","before"));
