 public static void tick(Minecraft mc){if(done)return;try{if(!started){started=true;mc.options.setCameraType(CameraType.THIRD_PERSON_BACK);mc.setScreen(null);mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst();var w=p.serverLevel();p.stopRiding();p.teleportTo(w,1000.5,211,2.5,0,0);var h=SivkaContent.ENTITY.get().create(w);h.moveTo(1000.5,211,2.5,0,0);var b=new SivkaBonds.Bond(p.getUUID());b.stage=7;b.entity=h.getUUID();SivkaBonds.get(w).bonds.put(p.getUUID(),b);SivkaBonds.get(w).setDirty();h.owner=p.getUUID();h.bond=b.id;h.generation=b.generation;var tag=new net.minecraft.nbt.CompoundTag();h.addAdditionalSaveData(tag);tag.putBoolean("SivkaAirborne",true);h.readAdditionalSaveData(tag);w.addFreshEntity(h);p.startRiding(h,true);});}if(!(mc.player.getVehicle() instanceof SivkaEntity h))return;horse=h;ticks++;if(ticks>=220){done=true;Files.createDirectories(O);Files.writeString(O.resolve("receipt.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(Map.of("status","CAPTURED_OWNER_REVIEW_PENDING","master_volume",mc.options.getSoundSourceOptionInstance(net.minecraft.sounds.SoundSource.MASTER).get(),"frames",frames,"scope","actual Minecraft renderer and current SivkaMesh/SivkaClient, fixed pose/camera; not gameplay")));mc.stop();}}catch(Throwable ex){ex.printStackTrace();done=true;mc.stop();}}
 public static void pre(Minecraft mc){if(done||horse==null||ticks<60)return;int i=(ticks-60)/20;if(i>=PHASES.length)return;try{horse.setId(200000);horse.tickCount=200;horse.setPos(1000.5,211,2.5);horse.setYRot(0);horse.yBodyRot=horse.yBodyRotO=horse.yHeadRot=horse.yHeadRotO=0;horse.setOldPosAndRot();value("SPEED",0);value("BANK",0);value("LIFT",0);value("PHASE",PHASES[i]);var seat=horse.getPassengerRidingPosition(mc.player);var position=seat.subtract(mc.player.getVehicleAttachmentPoint(horse));mc.player.setPos(position);mc.player.setYRot(0);mc.player.yBodyRot=mc.player.yBodyRotO=mc.player.yHeadRot=mc.player.yHeadRotO=0;mc.player.setOldPosAndRot();float partial=mc.getTimer().getGameTimeDeltaPartialTick(true);value("PHASE",PHASES[i]-partial/14.4F);}catch(Exception ex){ex.printStackTrace();done=true;mc.stop();}}
